"""Record actual emitted section/local-frame costs without inventing latency."""
from pathlib import Path
import hashlib,json,re
from run_dma_depth import target_units
ROOT=Path(__file__).resolve().parents[1];RECEIPT='reviews/v5/expansion/legacy_advanced_dma/current_validation.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 d=json.loads((ROOT/RECEIPT).read_text());assert d['passed'];rows={r['label']:r for r in d['checks']};profiles=[]
 for target in ['f439','h745-m7','h745-m4']:
  for cc in ['arm-none-eabi-gcc','clang']:
   for opt in ['-O0','-O3']:
    tag=target+'-'+cc+opt;r=rows[tag+' cost'];raw=(ROOT/r['raw']).read_text();sections=[]
    for name,size,address in re.findall(r'^(\S+)\s+(\d+)\s+(\d+)\s*$',raw,re.M):sections.append(dict(name=name,bytes=int(size),address=int(address)))
    stack=[]
    for path,h in d['outputs_sha256'].items():
     if '/'+tag+'/' in path and path.endswith('.su'):
      assert sha(ROOT/path)==h
      for line in (ROOT/path).read_text().splitlines():
       parts=line.split('\t')
       if len(parts)==3:stack.append(dict(function=parts[0].split(':')[-1],local_frame_bytes=int(parts[1]),kind=parts[2],source=path))
    assert stack and sections
    imports={unit:(ROOT/rows[tag+' '+unit+' imports']['raw']).read_text().strip().splitlines() for unit,src in target_units(target)}
    profiles.append(dict(profile=tag,sections=sections,local_stack_frames=stack,object_imports=imports,linked_imports=(ROOT/rows[tag+' image closure']['raw']).read_text(),helpers='Original assessor/execution/support.c; compiler-generated byte operations remain visible in imports/map. No compiler runtime archive.'))
 out=dict(passed=True,input_sha256={RECEIPT:sha(ROOT/RECEIPT),'tools/summarize_dma_costs.py':sha(Path(__file__))},profiles=profiles,comparison=dict(admission='O(n^2) overlap checks,n<=4; fixed copied descriptors, no allocation.',poll='O(1) status/control work plus one next-descriptor configure; software SG contains a CPU scheduling gap.',cache='One clean per source/destination line, pre-invalidate destination and post-invalidate after quiescence; actual helper/provider imports retained.',peer='One HSEM take, fixed32-byte metadata maintenance and whole-payload receiver invalidation; bounded polling has no liveness/latency guarantee.'),limits=['Compiler local frames are observed, not full call-chain/interrupt peak stack.','No physical DMA duration, cache/interconnect bandwidth, peer latency or energy measurement.','Rebuild after target/optimization changes; costs are not portable golden outputs.'])
 p=ROOT/'reviews/v5/expansion/legacy_advanced_dma/cost_analysis.json';p.write_text(json.dumps(out,indent=2)+'\n');print(dict(passed=True,profiles=len(profiles),local_frames=sum(len(p['local_stack_frames']) for p in profiles)))
if __name__=='__main__':main()
